package mx.coberturapunto;
import org.junit.Test;import org.json.JSONObject;import java.io.*;import static org.junit.Assert.*;
public class UpdatePolicyTest {
 JSONObject valid()throws Exception{return new JSONObject().put("schemaVersion",1).put("packageName","mx.coberturapunto").put("latestVersionCode",27).put("minSupportedVersionCode",26).put("latestVersionName","1.0.2").put("sizeBytes",1000).put("downloadUrl","https://github.com/Gruktoolz/geopin-pro-releases/releases/download/v1.0.2/GeoPin-Pro-1.0.2.apk").put("sha256","a".repeat(64));}
 void reject(String key,Object v)throws Exception{JSONObject j=valid().put(key,v);try{new AppUpdater.Release(j);fail("Accepted invalid "+key+": "+v);}catch(Exception expected){}}
 @Test public void validVersionAndMinimum()throws Exception{var r=new AppUpdater.Release(valid());assertEquals(27,r.latest);assertEquals(26,r.minimum);assertTrue(25<r.minimum);assertFalse(26<r.minimum);}
 @Test public void rejectWrongAppsAndMalformedNumbers()throws Exception{reject("packageName","mx.coberturapunto.monitor");reject("latestVersionCode","27");reject("latestVersionCode",27.5);reject("latestVersionCode",-1);reject("minSupportedVersionCode",28);reject("sizeBytes",0);reject("sizeBytes",AppUpdater.MAX_APK+1);reject("sha256","bad");reject("latestVersionName","");reject("schemaVersion",2);}
 @Test public void rejectUnexpectedDownloadDestinations()throws Exception{for(String u:new String[]{"http://github.com/Gruktoolz/geopin-pro-releases/releases/download/v1/a.apk","https://github.com.evil.test/Gruktoolz/geopin-pro-releases/releases/download/v1/a.apk","https://github.com/other/project/releases/download/v1/a.apk","https://github.com:8443/Gruktoolz/geopin-pro-releases/releases/download/v1/a.apk","https://user@github.com/Gruktoolz/geopin-pro-releases/releases/download/v1/a.apk","https://github.com/Gruktoolz/geopin-pro-releases/releases/download/v1/a.apk?x=1"})reject("downloadUrl",u);}
 @Test public void rejectsFormerOwnerToUseCanonicalIdentity()throws Exception{reject("downloadUrl","https://github.com/former-owner/geopin-pro-releases/releases/download/v1/a.apk");}
 @Test public void boundedResponses()throws Exception{assertArrayEquals(new byte[16],AppUpdater.readLimited(new ByteArrayInputStream(new byte[16]),16));try{AppUpdater.readLimited(new ByteArrayInputStream(new byte[17]),16);fail("Response too large accepted");}catch(IOException expected){}}
 @Test public void digestAndRedirectPolicy(){assertEquals("00ff12",AppUpdater.hex(new byte[]{0,-1,18}));assertTrue(AppUpdater.downloadHost("release-assets.githubusercontent.com"));assertFalse(AppUpdater.downloadHost("github.com.evil.test"));}
}
